import{_ as e,o as a,c as i,a3 as s}from"./chunks/framework.BwzYn71E.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"translationSource":{"title":"萌新入坑流程及注意事项「武陵篇」","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=L0hsh88XqUwFigit3JjUTg","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/new-player-progression-and-precautions-wuling"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/new-player-progression-and-precautions-wuling"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/new-player-progression-and-precautions-wuling"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/new-player-progression-and-precautions-wuling"}]]},"headers":[],"relativePath":"new-player-progression-and-precautions-wuling.md","filePath":"logistics/src/page-L0hsh88XqUwFigit3JjUTg.md"}'),n={name:"new-player-progression-and-precautions-wuling.md"};function d(o,t,r,l,c,p){return a(),i("div",null,[...t[0]||(t[0]=[s('<div class="logistics-content"><h1 id="new-player-progression-and-precautions-wuling" tabindex="-1">New-Player Progression and Precautions: Wuling <a class="header-anchor" href="#new-player-progression-and-precautions-wuling" aria-label="Permalink to &quot;New-Player Progression and Precautions: Wuling&quot;">​</a></h1><blockquote><p>Source page ID: <code>L0hsh88XqUwFigit3JjUTg</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=L0hsh88XqUwFigit3JjUTg" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span class="mark-grey"><em>Before reading: players rushing progression and players taking their time have vastly different experiences in Wuling. Rushing requires very tight scheduling and resource allocation; relaxed play has little pressure and will not be discussed in detail. This guide helps players rushing progression plan their route and use resources sensibly.</em></span></p><p><span id="source-block-8umcWj3tmbjudi7FUj2RZm"></span></p><h3 id="stage-zero-what-to-know-before-entering-wuling" tabindex="-1">Stage Zero: What to Know Before Entering Wuling <a class="header-anchor" href="#stage-zero-what-to-know-before-entering-wuling" aria-label="Permalink to &quot;Stage Zero: What to Know Before Entering Wuling&quot;">​</a></h3><p>1.After creating an account and entering the game, follow the fixed opening story and tutorial. Once events unlock, accept the special “Main Story Early Unlock: Wuling” event mission to enter Wuling directly.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6141527773096cad.q90-531f0ac7ce0f246c.webp" alt="New-Player Progression and Precautions: Wuling"></p><p>2.Wuling&#39;s main-story route is Jingyu Valley → Wuling City → Qingbo Stockade → Marker Stone → Yinglung Pass → North Wuling Exclusion Zone → Si&#39;s Painting. The other areas are side-story maps.</p><p>3.Every blueprint in this guide needs water, Precipitation Acid, Inergen and Xiragen connected. The connections are marked with Control Ports in obvious locations. Unless specifically stated otherwise, each Control Port corresponds to one water/Precipitation Acid pump. The blueprints include many safeguards; modifying them on your own is not recommended.</p><p>4.Collect as many survey posts as possible while doing missions to accumulate Industry Points. If points are tight, unlock exactly what each stage&#39;s diagram shows. Otherwise, even after placing a blueprint you may be unable to use it, and some facilities&#39; output settings may even be disrupted!</p><p>5.Stock Bills are extremely tight early on. Spend every bit where it counts—on the blade&#39;s edge, not its back, handle or sheath! The upgrade/unlock priorities are shown below: red first, yellow next, then green. Upgrade the rest gradually from cheapest to most expensive.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-52d2854c15711ddd.q90-f6dcfe0cf2495fe3.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="mj0Hgpc1UecOGUlkDmaFqK"><p>Priority for area unlocks/upgrades and facility unlocks/upgrades</p></div><p>6.The diagram shows mission progress, construction level, mineral output and precautions at each milestone for players rushing progression. Every blueprint here matches the minimum mineral output at its stage, so mineral demand will not exceed supply.</p><p>7.Note that <span class="mark-red">this guide uses 11 blueprints in total</span>. Every stage uses embedded incremental blueprints that draw from or fill gaps in the previous stage&#39;s line. Ensure the previous stage&#39;s blueprints are complete and unmodified! Otherwise, later blueprints may fail to be placed, or may be placed but fail to run.</p><p>8.This is a base-building guide; content outside base building is not covered unless necessary.</p><p>9.Skipping Valley IV and entering Wuling directly unlocks Valley IV technology and gives 50 of each facility it unlocks. However, you will still lack enough Depot Unloaders, and the Amethyst Ore needed to craft them is available only in Valley IV. Although Valley IV&#39;s main-story tutorial asks you to make Amethyst Parts, its earlier steps have you place a Portable Mining Rig on Originium Ore south of the Hub base, manually collect the ore, put it into a powered Refining Unit, and submit the resulting Origocrust. New players may copy that approach: place a Portable Mining Rig on Amethyst Ore west of the base → manually collect Amethyst Ore → put it in a Refining Unit for Amethyst Fiber → manually move that fiber into a Fitting Unit for Amethyst Parts… So, by Stage Five at the latest, set up an Amethyst Parts line in Valley IV to produce the essential facilities!</p><p>10.As of October 30, 2026, these blueprints have undergone over 1 month of development and testing, with no problems so far. If you encounter issues, discuss them in the group chat; whenever I am around, I will answer.</p><p><span id="source-block-zyNrWvjZ8IZLxWcFn70ZSH"></span></p><h3 id="stage-one-finish-wuling-city-s-main-story-unlock-wuling-base-and-sky-king-flats-outpost" tabindex="-1">Stage One: Finish Wuling City&#39;s Main Story (Unlock Wuling Base and Sky King Flats Outpost) <a class="header-anchor" href="#stage-one-finish-wuling-city-s-main-story-unlock-wuling-base-and-sky-king-flats-outpost" aria-label="Permalink to &quot;Stage One: Finish Wuling City&#39;s Main Story (Unlock Wuling Base and Sky King Flats Outpost)&quot;">​</a></h3><p>Connect all mining spots in Jingyu Valley and Wuling City, reaching 250/min Originium Ore and 60/min Ferrium Ore, with construction level 2. Pick up the required plants around the base; only 1 of each is needed. Unlock the 5 items shown in the Industry Points diagram. A mission unlocks the environmental monitoring station without spending Stock Bills and gives a photography assignment: your first payout of 12500 Stock Bills! Use it to unlock Wuling City Base&#39;s depot bus. Place the first blueprint there and connect its Control Ports to two water pumps for the initial startup.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a66295804b10cfd6.q90-d4558e8f7a7f4071.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="GeNpI8CQpEYcS7V56O8qnD"><p>Location of the first plant</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a84175f2bcee0dbe.q90-aed8151b3ff9fbb5.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="Si42vhFo8IGriYXHo4ZZMC"><p>Industry Points unlocks</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-41e6d85e352201de.q90-9ac91b83eb8cd2bf.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="eDIJ4SQYWfU78yh0MwiVKO"><p>Wuling City area unlocks</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-533d9c5f18ebaf92.q90-3a397532af36ba06.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="bSoYZwaunxj0CLhCXCzNCG"><p>Wuling City blueprint</p></div><p><span class="mark-blue">[Stage 1 – Wuling] EF01Oe4582508IoO9oe4</span></p><p>Wuling City: with the river on the left, place <span class="mark-blue">[Stage 1 – Wuling]</span>. It consumes 180/min Originium Ore and 60/min Ferrium Ore. The depot initially needs only one Yazhen and one Sandleaf. During startup, approximately 325 Yazhen, 325 Sandleaf, 3250 Ferrium Parts and 3250 Xiranite accumulate in the depot. Once stable, it produces 6/min LC Wuling Batteries and 3/min Yazhen Syringes [C], with normal total power generation of 1800.</p><p>Then continue with the missions…</p><p><span id="source-block-vMNBmjr3Ce6UXxKUoVtfzH"></span></p><h3 id="stage-two-finish-marker-stone-s-main-story-unlock-marker-stone-outpost" tabindex="-1">Stage Two: Finish Marker Stone&#39;s Main Story (Unlock Marker Stone Outpost) <a class="header-anchor" href="#stage-two-finish-marker-stone-s-main-story-unlock-marker-stone-outpost" aria-label="Permalink to &quot;Stage Two: Finish Marker Stone&#39;s Main Story (Unlock Marker Stone Outpost)&quot;">​</a></h3><p>Fully connect the mining spots, remembering the new spots that appear in Wuling City and Jingyu Valley. Reach 360/min Originium Ore, 90/min Ferrium Ore and 120/min Cuprium Ore, with construction level 5. Unlock the 4 items shown in the Industry Points diagram. Expand Wuling Base&#39;s area once and add one Depot Bus Section. Ways to obtain the required Stock Bills, from easiest to hardest:</p><ol class="logistics-tutorial-steps"><li value="1">Unlocking an outpost immediately gives it a Stock Bill reserve at half its cap. Exchange batteries/medicine to collect it.</li><li value="2">Besides the environmental monitoring assignment provided by the main story, Wuling has another worth 54000 Stock Bills. Take a photo at the specified location.</li><li value="3">The storage node at Wuling&#39;s lower right costs 12500 Stock Bills to unlock and offers 3 orders worth 11w+ Stock Bills each (w stands for ten thousand). This is time-consuming and laborious, so it is not recommended.</li></ol><p><img src="/endfield-skydoc/logistics/src/assets/images/img-79516508bbbf67c6.q90-0d29767163042fe8.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="0QbriENSePo5uDSJRFmo5h"><p>Industry Points unlocks</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-bbf00d1d6c435f3c.q90-6d1ee1b0dabbaf4c.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="Qorex3Hz6jJlYCBDqxaDVY"><p>Wuling area expansion and additional depot bus sections</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e84a6b10561216d0.q90-75a37eab97234e8c.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-94df1e587c326e5a.jpeg" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="gcojM9LeIYvPpDqpaZB6GC"><p>Stage 2 blueprints</p></div><p><span class="mark-blue">[Stage 2 – Wuling 1] EF014AE2IO21I3i3E71A</span></p><p><span class="mark-blue">[Stage 2 – Wuling 2] EF014AE2IO21I309E71A</span></p><p>Wuling City: select the first blueprint and move it to the base&#39;s upper left. Join <span class="mark-blue">[Stage 2 – Wuling 1]</span> underneath and <span class="mark-blue">[Stage 2 – Wuling 2]</span> at the upper right, then reconnect 6 water pumps on the left. After startup, 3250 Cuprium Parts accumulate. Once stable, the AIC provides 8.75 LC Wuling Batteries, 6 Yazhen Syringes [A] and 4.5 Yazhen Syringes [C] per minute, with normal power generation of 3400 (minor fluctuations do not affect production). This meets Stock Bill exchange requirements until all three outposts reach level 2.</p><p><span id="source-block-kq2WoDKmVzCIvmtd0NmIX9"></span></p><h3 id="stage-three-finish-the-north-wuling-exclusion-zone-s-main-story-unlock-yinglung-pass-outpost" tabindex="-1">Stage Three: Finish the North Wuling Exclusion Zone&#39;s Main Story (Unlock Yinglung Pass Outpost) <a class="header-anchor" href="#stage-three-finish-the-north-wuling-exclusion-zone-s-main-story-unlock-yinglung-pass-outpost" aria-label="Permalink to &quot;Stage Three: Finish the North Wuling Exclusion Zone&#39;s Main Story (Unlock Yinglung Pass Outpost)&quot;">​</a></h3><p>Connect every mining spot and gas vent: 360/min Originium Ore, 90/min Ferrium Ore, 220/min Cuprium Ore and 30/min Xiragen, with construction level 7. Unlock every Industry Point except the turrets and the 12 Forges of the Sky unlocked by the “Bring Back the Spring” quest (provisional name). Unlock the depot bus at both Marker Stone and Yinglung Pass.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-89f51652e86641df.q90-dcb1e298e5831f63.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="8ZjoJLuQLXZkaUpEYilnQq"><p>Industry Points unlocks</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-75c143b0a487b178.q90-3bbc8c8d92504ec1.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="h8RPifLjRreztPqmsx8qG0"><p>Marker Stone area unlocks</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3d8a536056c6db92.q90-2c563c4f5a335a93.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="C7hnmMcWHbVLX8LOvLGZ9K"><p>Yinglung Pass area unlocks: red is required; blue is optional as needed</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e93ca7dd9cc5e63b.q90-289dda5ce67397d5.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="iOnDBt3AOeaEYOEMV42sN2"><p>Marker Stone blueprint</p></div><p><span class="mark-blue">[Stage 3 – Marker Stone] EF012UOEu5E6u844eIOo</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b57acb48b18ea5c2.q90-918a808d3419fe0b.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="CkoiAg2Xgay1SvT0ANuqlG"><p>Yinglung Pass blueprint</p></div><p><span class="mark-blue">[Stage 3 – Yinglung 1] EF01E75O34O93o0e3uIa</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3eaac66097f02ecc.q90-ead9e0cac784d135.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b3f46f89ecca6ac7.q90-bd25add93deffe16.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="RYhgMWylwrTNFFKDovOK6S"><p>Yinglung Pass supplementary blueprint</p></div><p><span class="mark-blue">[Stage 3 – Yinglung 2] EF015i24oE4aou61eIoe</span></p><p>Marker Stone: with the pond at the lower left and the acid pool below, place <span class="mark-blue">[Stage 3 – Marker Stone]</span>. Connect 5 water pumps (you may hit the pipe-length limit; add any pipe logistics component, such as a Pipe Bridge, outside the area) and Inergen (80/min). Connect 5 water pumps (you may hit the pipe-length limit; add any pipe logistics component, such as a Pipe Bridge, outside the area) and Inergen (80/min).</p><p>Yinglung Pass: with the survey post/open ground below, place <span class="mark-blue">[Stage 3 – Yinglung 1]</span>. On the left, connect Inergen (≥80/min), two water pumps, one acid pump and one Xiragen supply. Connect the later Xiragen supplies from Gapfill Outpost (provisional name) and Cedar Forest in order from bottom to top as they unlock. The right side has a 12/min Liquid Xiranite outlet for the Gapfill Outpost mission.</p><p>If this feels too slow, expand the base area once, leave the original blueprint in place, and add <span class="mark-blue">[Stage 3 – Yinglung 2]</span>. Connect one water pump at the upper left, then connect its conduit output of 42/min Liquid Xiranite. The mission has 5 locations requiring 5000 units each; each takes about 2h to complete.</p><p>After startup, accumulate 325 Canned Heavy Liquid Xiranite. Once stable, the AIC provides 8.75 LC Wuling Batteries, 6 Yazhen Syringes [A], 4.5 Yazhen Syringes [C] and 6 Heavy Xiranite per minute.</p><p><span id="source-block-pugiJMZLp9hN1B6JlOQMK7"></span></p><h3 id="stage-four-complete-the-side-story-maps-cangjian-valley-experimental-park-cedar-forest-and-gapfill-outpost-in-the-north-wuling-exclusion-zone-and-unlock-some-facilities" tabindex="-1">Stage Four: Complete the Side-Story Maps (Cangjian Valley, Experimental Park, Cedar Forest, and Gapfill Outpost in the North Wuling Exclusion Zone) and Unlock Some Facilities <a class="header-anchor" href="#stage-four-complete-the-side-story-maps-cangjian-valley-experimental-park-cedar-forest-and-gapfill-outpost-in-the-north-wuling-exclusion-zone-and-unlock-some-facilities" aria-label="Permalink to &quot;Stage Four: Complete the Side-Story Maps (Cangjian Valley, Experimental Park, Cedar Forest, and Gapfill Outpost in the North Wuling Exclusion Zone) and Unlock Some Facilities&quot;">​</a></h3><p>Unlock or upgrade facilities costing 10w Stock Bills or less (w = ten thousand), and connect every mining spot and gas vent: 500/min Originium Ore, 90/min Ferrium Ore, 330/min Cuprium Ore and 120/min Xiragen, with construction level 10. Unlock all Industry Points except the turrets. Expand Wuling Base once to its maximum 80*80 area. Add one depot bus section at Marker Stone and expand it to maximum area. Expand Yinglung Pass once <span class="mark-red">(if you already expanded it for the previous stage&#39;s supplementary blueprint, do not expand it again!)</span></p><p>If, after unlocking the areas, you lack Stock Bills for facility unlocks/upgrades, your supply at this point is 380/min Originium Ore, 90/min Ferrium Ore, 310/min Cuprium Ore and 120/min Xiragen, with construction level 7. You can defer the Yinglung Pass blueprint until you reach the required mineral output.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fa822810c7b2a8d2.q90-803d0604a51badb7.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="RPmScpfrjRjEHAiOkDHVzy"><p>Industry Points unlocks</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-684b31d86fc52b8e.q90-b6a8741f01dcf9ba.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="7ygNDsu0npxoYGhJCffswv"><p>Wuling City area unlocks</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d6f9e49310d11d13.q90-a72a291feba9107b.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="8n8d5UQWgzWrzL54jSoUVg"><p>Marker Stone area unlocks</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-24fb880d6bcaccbf.q90-cf2ebf2d97486d37.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="dnfYBb9YFzosg3iYyuOEJU"><p>Yinglung Pass area unlocks</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-332a94579c1bbfc3.q90-b9a3d15d5b65bbc1.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-631f56ad99eba4ce.q90-9345fc62f8949550.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="8lr8MQsaPtT2GKC9pY7Gua"><p>Wuling City blueprint</p></div><p><span class="mark-blue">[Stage 4 – Wuling] EF01Oe4582508IIi9oe4</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e0eec934d65c2653.q90-1b75d548aa58e23d.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-824a3366d29819a9.q90-e616d1ce3695acdb.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="notL0qhYdL1lDqkfqFXzej"><p>Marker Stone blueprint</p></div><p><span class="mark-blue">[Stage 4 – Marker Stone] EF016u09Aa94A79oO83e</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-55f155da3237f9b2.q90-27c3735bed818abc.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c82394544de47e8e.q90-e701c578fdb1852e.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="AbyvJbqbN9hWfNlEk0n6J0"><p>Yinglung Pass blueprint</p></div><p><span class="mark-blue">[Stage 4 – Yinglung] EF01ao61e91OeAeaou5e</span></p><p>Wuling City: with the river below, place <span class="mark-blue">[Stage 4 – Wuling]</span> above the existing setup. Connect two water pumps on the right. Connect the unconnected conduit at the upper left to the Purification Node, or to 4 sewage-treatment units. <span class="mark-red">(The camera angle changed; I took the screenshot incorrectly.)</span></p><p>Marker Stone: with the pond at the lower left, delete the water pipes, including logistics components, to the left of the water label. Retain only the original 30×30 blueprint and move that part to the lower left. Place <span class="mark-blue">[Stage 4 – Marker Stone]</span>. Connect the 5 water pumps and Inergen on the left, and 4 water pumps plus 1 Precipitation Acid supply below. If you demolished the existing setup and replaced the previous stage&#39;s Marker Stone blueprint, wait for that old blueprint to warm up again (about 5 minutes) before placing this stage&#39;s blueprint.</p><p>Yinglung Pass: with the survey post below, place the previous stage&#39;s supplementary blueprint <span class="mark-red">(skip this if you already placed it!)</span>, then place <span class="mark-blue">[Stage 4 – Yinglung]</span>.</p><p>Once stable, the AIC provides 5.75 LC Wuling Batteries, 6 Yazhen Syringes [A], 4.5 Yazhen Syringes [C], an adaptive 18–34.5 Heavy Xiranite, and 6 Pyrrolite Parts per minute. Removing one Thermal Bank at Marker Stone now gives you a complete endgame setup for version 1.6. The remaining content supplements capacity to ensure sufficient output and build stocks for gear crafting, mission submissions and protection against production losses from shutdowns.</p><p><span id="source-block-4qawSeWZPB4KZUPWeOghF4"></span></p><h3 id="stage-five-unlock-and-upgrade-almost-all-facilities-with-almost-all-outposts-at-level-4" tabindex="-1">Stage Five: Unlock and Upgrade Almost All Facilities, with Almost All Outposts at Level 4 <a class="header-anchor" href="#stage-five-unlock-and-upgrade-almost-all-facilities-with-almost-all-outposts-at-level-4" aria-label="Permalink to &quot;Stage Five: Unlock and Upgrade Almost All Facilities, with Almost All Outposts at Level 4&quot;">​</a></h3><p><span class="mark-red">Warning! This stage requires a production line in Valley IV! See Stage Zero, point 9.</span></p><p>Unlock and upgrade almost all facilities, bring almost every outpost to level 4, and connect every mining spot and gas vent: 510/min Originium Ore, 120/min Ferrium Ore, 540/min Cuprium Ore and 150/min Xiragen. Add one Depot Bus Section at Wuling City.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-dce0f990580d95c9.q90-e79f6eaf9b930c5d.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="JcbJMi79pp3HlhqTpRtFW2"><p>Wuling City area unlocks</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-313161c5fd1bc860.q90-425a83273725b72e.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fad031d8e83d56ab.q90-4f86ad1b19958d83.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="W8SImq6joKJdEGQFfIokue"><p>Wuling City blueprint [Stage 5 – Wuling]</p></div><p><span class="mark-blue">[Stage 5 – Wuling] EF01U9e72i7u2Oo37Oa8</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6d5d6b876752182f.q90-ed72f3c4d3605e7c.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-45cdc9c36a7d7443.q90-fc69ab05322c515e.webp" alt="New-Player Progression and Precautions: Wuling"></p><div class="logistics-image-caption" data-source-block="8zRNlEtAIcK3IRFuavOgvl"><p>Marker Stone blueprint</p></div><p><span class="mark-blue">[Stage 5 – Marker Stone] EF01u2836o3A6054AoOU</span></p><p>Wuling City: with the river below, place <span class="mark-blue">[Stage 5 – Wuling]</span> at the upper right. Connect 4 water pumps on the right, and connect the two unconnected conduits above to the two extra sewage-treatment ports of the level-3 Purification Node.</p><p>Marker Stone: with the pond at the lower left, place <span class="mark-blue">[Stage 5 – Marker Stone]</span> at the upper right. <span class="mark-red">(Marker Stone&#39;s pipe-logistics capacity is extremely tight. To place this blueprint, ensure there are no more than 6 pipe logistics components outside the AIC area.)</span></p><p>Once stable, the AIC provides 5.75 LC Wuling Batteries, 6 Yazhen Syringes [A], 4.5 Yazhen Syringes [C], an adaptive 18–34.5 Heavy Xiranite, 12 Pyrrolite Parts and 4.5 SC Wuling Batteries per minute (the source writes the last rate as “4,5”). This is expected to cover Stock Bill exchanges through Wuling&#39;s final version, without adding further AIC facilities.</p><p><span class="mark-green">At this stage your AIC is already fully developed, but these permanent blueprints produce as many as 6 products, requiring frequent product switching when exchanging for Stock Bills at outposts. If you want higher output or a setup with a fixed product for each outpost interaction, switch to a package you like: for example, the maximum-gross-output or maximum-net-output plans in this documentation, my other AIC layouts on bilibili, or guides from creators outside our team such as MR流星飞, 萧然Q and 魔法ZC目录.</span></p><p><span id="source-block-G2fRzuNNA2geXllT7v8IME"></span></p><h3 id="appendix-supporting-information" tabindex="-1">Appendix: Supporting Information <a class="header-anchor" href="#appendix-supporting-information" aria-label="Permalink to &quot;Appendix: Supporting Information&quot;">​</a></h3><p><span id="source-block-sXmHFgtj4mn8yE1gANNnzi"></span></p><h4 id="appendix-one-stages-key-milestone-information-minimum-mineral-output-construction-levels-and-precautions" tabindex="-1">Appendix One: Stages, Key Milestone Information, Minimum Mineral Output, Construction Levels and Precautions <a class="header-anchor" href="#appendix-one-stages-key-milestone-information-minimum-mineral-output-construction-levels-and-precautions" aria-label="Permalink to &quot;Appendix One: Stages, Key Milestone Information, Minimum Mineral Output, Construction Levels and Precautions&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Resource output</th><th></th><th></th><th></th><th></th><th></th><th></th><th></th><th></th><th>Stage classification</th></tr></thead><tbody><tr><td>Milestone</td><td>Story progress (completed through)</td><td>Construction level</td><td>Originium Ore</td><td>Ferrium Ore</td><td>Cuprium Ore</td><td>Inergen</td><td>Xiragen</td><td>Notes</td><td></td></tr><tr><td>1</td><td>Jingyu Valley Outpost</td><td>2</td><td>250</td><td>60</td><td>0</td><td>0</td><td>0</td><td>-</td><td>Stage 1 – Preparation</td></tr><tr><td>2</td><td>Qingbo Stockade</td><td>3</td><td>290</td><td>90</td><td>40</td><td>0</td><td>0</td><td>Add Wuling mining rigs</td><td><u>Stage 2 – Transition 1</u></td></tr><tr><td>3</td><td>Marker Stone Outpost + mask conveyor belt</td><td>5</td><td>360</td><td>90</td><td>120</td><td>0</td><td>0</td><td>Add Jingyu Valley and Qingbo Stockade mining rigs</td><td></td></tr><tr><td>4</td><td>North Wuling Exclusion Zone gate + Yinglung Pass Outpost</td><td>6</td><td>360</td><td>90</td><td>120</td><td>420</td><td>0</td><td>Add Inergen at each outpost</td><td><u>Stage 3 – Transition 2</u></td></tr><tr><td>5</td><td>Main story complete</td><td>7</td><td>360</td><td>90</td><td>220</td><td>460</td><td>30</td><td>-</td><td></td></tr><tr><td>6</td><td>Cangjian Valley complete</td><td>7</td><td>360</td><td>90</td><td>240</td><td>460</td><td>30</td><td>Explosives may be needed (theoretically sufficient); Liquid Heavy Xiranite is needed to unlock deposits</td><td><u>Stage 4 – Supplement 1</u></td></tr><tr><td>7</td><td>Experimental Park</td><td>7</td><td>380</td><td>90</td><td>260</td><td>460</td><td>30</td><td>Liquid Heavy Xiranite is required to enter the area</td><td></td></tr><tr><td>8</td><td>Cedar Forest</td><td>7</td><td>380</td><td>90</td><td>310</td><td>460</td><td>80</td><td></td><td></td></tr><tr><td>9</td><td>Gapfill Outpost</td><td>7</td><td>380</td><td>90</td><td>310</td><td>460</td><td>120</td><td></td><td></td></tr><tr><td>10</td><td>Unlock all facilities and upgrade those below 10w Stock Bills</td><td>10</td><td>500</td><td>90</td><td>330</td><td>460</td><td>120</td><td>Resource recycling fully upgraded; Wuling storage node level 2; Jingyu Valley material dispatch level 2; everything else level 1</td><td><u>Stage 5 – Supplement 2</u></td></tr><tr><td>11</td><td>Unlock all facilities and upgrade those below 30w Stock Bills</td><td>15</td><td>540</td><td>90</td><td>390</td><td>460</td><td>120</td><td>Additional: upgrade the three outposts to level 2</td><td></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Issue summary</th><th></th><th></th><th></th><th></th><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td>1</td><td>Gear is a major early bottleneck. Crystallon gear cannot be crafted; only small amounts are awarded by levels after Authority Level 28. Players rushing progression may get stuck here.</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td>Unlocking material-dispatch terminals requires a Valley IV mission, potentially affecting regional construction-level progress.</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td>Side missions that open new areas have technology-tree requirements, such as more Forges of the Sky and Heavy Xiranite. Placing blueprints only two or three times is difficult; small add-on modules are needed.</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td>The Xiranite progression chain is rather involved: one crucible → two → 4 → Heavy Xiranite; 8 crucibles → Experimental Park side quest → 12; unlock the Gas Dispersing Unit → a new 12-crucible Xiranite setup.</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td>Pyrrolite is one of the most important outputs, but requires many technology points. Perhaps a technology-point planning guide is needed?</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td>Turret-related technology costs 9 Industry Points altogether and can be skipped initially. Multi-port conduits can also be skipped unless essential.</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td>Jingyu Valley Outpost upgrades very slowly but demands basic products (LC Wuling Batteries and basic medicine). Consider product types as well as capacity.</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><span id="source-block-mpyQnWNl21Spw9V57lsmRt"></span></p><h4 id="appendix-two-aic-area-upgrade-costs-facility-upgrade-costs-and-outpost-stock-bill-income" tabindex="-1">Appendix Two: AIC Area Upgrade Costs, Facility Upgrade Costs and Outpost Stock Bill Income <a class="header-anchor" href="#appendix-two-aic-area-upgrade-costs-facility-upgrade-costs-and-outpost-stock-bill-income" aria-label="Permalink to &quot;Appendix Two: AIC Area Upgrade Costs, Facility Upgrade Costs and Outpost Stock Bill Income&quot;">​</a></h4><table tabindex="0"><thead><tr><th>AIC area upgrades (unit: 10,000 Stock Bills)</th><th></th><th></th><th></th><th></th><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td>Item</td><td>Location</td><td>Area expansion 1</td><td>Area expansion 2</td><td>Depot bus 1</td><td>Depot bus 2</td><td>Depot bus 3</td><td>Depot bus 4</td><td>Depot bus 5</td></tr><tr><td>Base upgrade</td><td>Wuling City</td><td>2</td><td>16</td><td>1</td><td>4</td><td>16</td><td>30</td><td>50</td></tr><tr><td></td><td>Jingyu Valley</td><td>2</td><td>16</td><td>1</td><td>4</td><td>16</td><td>30</td><td></td></tr><tr><td></td><td>Marker Stone</td><td>30</td><td>90</td><td>15</td><td>60</td><td>90</td><td>120</td><td></td></tr><tr><td></td><td>Yinglung Pass</td><td>45</td><td>120</td><td>30</td><td>80</td><td>120</td><td>160</td><td></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Wuling regional construction upgrades (unit: 10,000 Stock Bills)</th><th></th><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td></td><td></td><td>Unlock</td><td>Upgrade to 2</td><td>Upgrade to 3</td><td>Upgrade to 4</td></tr><tr><td>Environmental monitoring</td><td>Wuling City</td><td>0</td><td>18.6</td><td>25</td><td>45</td></tr><tr><td></td><td>Marker Stone</td><td>3</td><td>24</td><td>32</td><td>50</td></tr><tr><td>Storage node</td><td>Wuling City</td><td>1.25</td><td>7.2</td><td>15</td><td>90</td></tr><tr><td></td><td>Experimental Park</td><td>6</td><td>16</td><td>20</td><td>120</td></tr><tr><td>Resource recycling</td><td>Wuling City</td><td>0.01</td><td>0.1</td><td>0.5</td><td>2</td></tr><tr><td></td><td>Jingyu Valley 1</td><td>0.01</td><td>0.1</td><td>0.5</td><td>2</td></tr><tr><td></td><td>Jingyu Valley 2</td><td>0.01</td><td>0.1</td><td>0.5</td><td>2</td></tr><tr><td></td><td>Jingyu Valley 3</td><td>0.01</td><td>0.1</td><td>0.5</td><td>2</td></tr><tr><td></td><td>Qingbo Stockade</td><td>0.01</td><td>0.1</td><td>0.5</td><td>2</td></tr><tr><td>Material dispatch</td><td>Jingyu Valley</td><td>0.5</td><td>6.4</td><td>45</td><td>140</td></tr><tr><td></td><td>Marker Stone</td><td>3</td><td>40</td><td>65</td><td>100</td></tr><tr><td></td><td>Yinglung Pass</td><td>5</td><td>60</td><td>-</td><td>-</td></tr><tr><td>Purification Node</td><td>Experimental Park</td><td>0</td><td>25</td><td>45</td><td>120</td></tr><tr><td>Training platform</td><td>Cangjian Valley</td><td>1</td><td>15</td><td>60</td><td></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Base outpost Stock Bill income (unit: Stock Bills/min)</th><th></th><th></th><th></th><th></th><th>Fully configured</th></tr></thead><tbody><tr><td>Region</td><td>Level 1</td><td>Level 2</td><td>Level 3</td><td>Level 4</td><td>Fully configured</td></tr><tr><td>Jingyu Valley</td><td>78</td><td>215</td><td>448</td><td>500</td><td>700</td></tr><tr><td></td><td>-</td><td>-</td><td>Requires Cuprium Parts</td><td>-</td><td>-</td></tr><tr><td>Marker Stone</td><td>55</td><td>140</td><td><span class="mark-green">325</span></td><td>380</td><td>456</td></tr><tr><td></td><td>-</td><td>-</td><td>-</td><td>-</td><td>-</td></tr><tr><td>Yinglung Pass</td><td>45</td><td>105</td><td>240</td><td>400</td><td>560</td></tr><tr><td></td><td>-</td><td>Requires Heavy Xiranite</td><td>-</td><td>Requires Pyrrolite Parts</td><td>-</td></tr><tr><td>Total</td><td>178</td><td>460</td><td>1013</td><td>1280</td><td>1716</td></tr></tbody></table><p><span id="source-block-jn8x5dettrDbYELViSiKQO"></span></p><h4 id="appendix-three-water-and-gas-pump-placement" tabindex="-1">Appendix Three: Water- and Gas-Pump Placement <a class="header-anchor" href="#appendix-three-water-and-gas-pump-placement" aria-label="Permalink to &quot;Appendix Three: Water- and Gas-Pump Placement&quot;">​</a></h4><p>Marker Stone Inergen</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d73e5e13c4ad6520.q90-97e1f96bcc5517d0.webp" alt="New-Player Progression and Precautions: Wuling"></p><p>Marker Stone water pumps</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-afc81a2914ca97bf.q90-08d897052a88fbc0.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-00fab86e6a67bffc.q90-e7d05947834cb1d0.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b044d0831c1312f2.q90-8771eff965d7848c.webp" alt="New-Player Progression and Precautions: Wuling"></p><p>To bypass the angler at the far left of Marker Stone, enter top-down view from the AIC area&#39;s upper right. You can then place water pumps regardless of the angler.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-43d368efaee205ce.q90-caac633ca3395547.webp" alt="New-Player Progression and Precautions: Wuling"></p><p>This guide does not use Jingyu Valley Outpost. If you later switch to the perfect-sub-base series mentioned in the documentation, however, you will need Jingyu Valley&#39;s 12-Xiranite-unit blueprint. Connect its water pumps as follows:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-cc9b6fd280d3e7bb.q90-7c011072b4d27aa7.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3a9c58a636b3f02d.q90-5b8430800bd9efae.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-78661be834f7b09e.q90-cf36e1af9158387b.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ba3467891e88e446.q90-2daf78b4bfde3c38.webp" alt="New-Player Progression and Precautions: Wuling"></p></div>',1)])])}const h=e(n,[["render",d]]);export{g as __pageData,h as default};
